import{_ as s,a8 as e,o as l,c as n,ah as i,K as t}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const f=JSON.parse('{"title":"细分行业 AI 案例检索：直接同行案例为零时的三层扩展法","description":"","frontmatter":{"type":"lesson","scope":"work","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["检索","案例调研","AI转型","方法论"]},"headers":[],"relativePath":"vault/Memory/Lessons/细分行业AI案例检索策略.md","filePath":"vault/Memory/Lessons/细分行业AI案例检索策略.md","lastUpdated":1789374053000}'),_={name:"vault/Memory/Lessons/细分行业AI案例检索策略.md"};function c(d,a,h,p,m,g){const o=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return l(),n("div",null,[a[0]||(a[0]=i('<h1 id="细分行业-ai-案例检索-直接同行案例为零时的三层扩展法" tabindex="-1">细分行业 AI 案例检索：直接同行案例为零时的三层扩展法 <a class="header-anchor" href="#细分行业-ai-案例检索-直接同行案例为零时的三层扩展法" aria-label="Permalink to “细分行业 AI 案例检索：直接同行案例为零时的三层扩展法”">​</a></h1><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to “问题”">​</a></h2><p>为帮老适（适老家具，天猫 TOP1）找同行 AI 化案例时发现：<strong>极细分赛道的直接对标公开案例几乎为零</strong>（5 路检索一致证实），且小团队（1 开发 + 1 管培生）的公开实战复盘也搜不到——企业不愿公开失败，小团队不写复盘。</p><h2 id="解法-三层相关度扩展-可信度标注" tabindex="-1">解法：三层相关度扩展 + 可信度标注 <a class="header-anchor" href="#解法-三层相关度扩展-可信度标注" aria-label="Permalink to “解法：三层相关度扩展 + 可信度标注”">​</a></h2><ol><li><strong>第一层（客群重合）</strong>：银发消费品牌（足力健、元生智能）——人群洞察可迁移</li><li><strong>第二层（品类/渠道相近）</strong>：家具家居电商（芝华仕、林氏、社淘、奥康）——工具与场景直接对口</li><li><strong>第三层（规模相近）</strong>：中小企业通案（IDC 数据、重庆智能体账本、台湾外贸失败案例）——失败教训比成功案例更有预警价值</li></ol><p>每个案例必标：主体、量化结果、来源可信度（官方案例页 &gt; 权威媒体 &gt; 从业者复盘 &gt; 厂商软文）、对委托方的借鉴点。</p><h2 id="附带发现-检索环境限制" tabindex="-1">附带发现（检索环境限制） <a class="header-anchor" href="#附带发现-检索环境限制" aria-label="Permalink to “附带发现（检索环境限制）”">​</a></h2><ul><li>微信公众号文章正文反爬严重（&quot;环境异常验证&quot;页），高价值文章常只能拿摘要——如实标注&quot;未读全文&quot;，建议用户人工打开核验</li><li>各搜索引擎轮流可用性不同（Google/DuckDuckGo 超时、cn.bing 中文分词失效、360/搜狗可用），需要多引擎轮换</li><li>厂商官方案例页（阿里云客户案例、极客公园深度报道）是技术细节密度最高的来源，优先抓全文</li></ul><h2 id="效果" tabindex="-1">效果 <a class="header-anchor" href="#效果" aria-label="Permalink to “效果”">​</a></h2><p>用此法为帮老适产出 14 环节约 40 个案例、5 个深挖案例，支撑了框架 v2 的全部修正输入。汇报叙事浓缩为三个故事（奥康成功 / 重庆账本失败 / 戚总店踩坑）即可撑起全部论据。</p>',10)),t(o),t(r)])}const A=s(_,[["render",c]]);export{f as __pageData,A as default};
